package com.zeptopluse.service; import com.zeptopluse.dto.CategoryResponse; import com.zeptopluse.mapper.CategoryMapper; import com.zeptopluse.repository.CategoryRepository; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import java.util.List; @Service @RequiredArgsConstructor public class CategoryService { private final CategoryRepository categories; private final CategoryMapper mapper; public List<CategoryResponse> list(){return categories.findByActiveTrueOrderByDisplayOrderAsc().stream().map(mapper::toResponse).toList();} }